function validate([nums]) {
  if (nums.length < 3 || nums.length > 100000) return 'nums needs 3 to 100000 values.';
  if (nums.some(v => v < -1000 || v > 1000)) return 'Each value is between -1000 and 1000.';
  const total = nums.reduce((a, b) => a + b, 0);
  const seen = {};
  for (const v of nums) seen[v] = (seen[v] || 0) + 1;
  const ok = nums.some(v => (total - v) % 2 === 0 && (seen[(total - v) / 2] || 0) > ((total - v) / 2 === v ? 1 : 0));
  return ok ? null : 'No entry can be the outlier: some entry must equal the sum of all entries except itself and one other.';
}

