function getLargestOutlier(nums) {
  let total = 0;
  const count = new Map();
  for (const num of nums) {
    total += num;
    count.set(num, (count.get(num) ?? 0) + 1);
  }
  let best = -Infinity;
  for (const outlier of count.keys()) {
    const rest = total - outlier;
    if (rest % 2 !== 0) continue;
    const sum = rest / 2;
    const available = count.get(sum) ?? 0;
    const needed = sum === outlier ? 2 : 1;
    if (available >= needed && outlier > best) {
      best = outlier;
    }
  }
  return best;
}

