function getLargestOutlier(nums) {
  // Try every ordered pair of positions: i is the outlier, j holds the sum of everything else.
  const total = nums.reduce((a, b) => a + b, 0);
  let best = null;
  for (let i = 0; i < nums.length; i++) {
    for (let j = 0; j < nums.length; j++) {
      if (i === j) continue;
      const specials = total - nums[i] - nums[j];
      if (nums[j] === specials && (best === null || nums[i] > best)) best = nums[i];
    }
  }
  return best;
}

