function generate(rand, size) {
  const n = size === 'large' ? 2000 : 3 + Math.floor(rand() * 8);
  const span = size === 'large' || rand() < 0.15 ? 1000 : 1 + Math.floor(rand() * 9);
  const pick = () => Math.floor(rand() * (2 * span + 1)) - span;
  const specials = Array.from({ length: n - 2 }, pick);
  // Nudge random specials until their total lands on a goal inside [-1000, 1000].
  const goal = Math.max(-1000, Math.min(1000, pick()));
  let total = specials.reduce((a, b) => a + b, 0);
  while (total !== goal) {
    const i = Math.floor(rand() * specials.length);
    const next = Math.max(-1000, Math.min(1000, specials[i] + goal - total));
    total += next - specials[i];
    specials[i] = next;
  }
  const outlier = rand() < 0.2 ? total : pick();
  const nums = [...specials, total, outlier];
  for (let i = nums.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [nums[i], nums[j]] = [nums[j], nums[i]];
  }
  return [nums];
}
